using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the default discriminator property from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator", and direct SQL queries reference c.Discriminator,
            // so we must preserve the old property name.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id values from "EntityType|KeyValue" (e.g. "Product|123") to just the
            // key value (e.g. "123"). Existing documents use the compound format, so we must preserve it
            // to keep FindAsync, point-reads, and direct SQL queries working.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // REMOVED: HasIndex() — EF Core 9 Cosmos provider now throws InvalidOperationException
        // for HasIndex calls. Cosmos DB indexing is managed via the container's indexing policy
        // (Azure Portal, Bicep, or Terraform), not through EF Core.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

