using Microsoft.EntityFrameworkCore;

class CosmosQuery
{
    // EF Core 9 Cosmos provider no longer supports synchronous I/O — all queries must be async.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — c.Discriminator is safe because we configured
        // HasDiscriminator<string>("Discriminator") to preserve the EF Core 8 property name.
        // Without that configuration, EF Core 9 would default to "$type".
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Changed from ToList() to ToListAsync() — sync I/O throws in EF Core 9 Cosmos provider.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

